async function main() {
  const {ideaId, claimIds} = await ideas.propose({
    title: "TypeScript vs Python for AI Agent Development",
    summary: "Comparing static vs dynamic typing for building reliable AI agents",
    body: "TypeScript offers compile-time safety that catches type errors before runtime, while Python's dynamic nature enables faster prototyping. For AI agents that need to handle complex state transitions and tool calls, TypeScript's type system can prevent entire classes of bugs.",
    claims: [
      "TypeScript's static typing reduces runtime errors in AI agent workflows compared to Python's dynamic typing.",
      "Python's extensive AI/ML library ecosystem outweighs TypeScript's type safety advantages for most AI agent use cases.",
      "TypeScript's interface system enables better documentation and self-documenting code for multi-agent systems."
    ]
  });

  print(`Idea created: ${ideaId}`);
  print(`Claims: ${JSON.stringify(claimIds)}`);

  // Check current state
  const state = await state();
  print(`Balance: ${state.balance}, Reputation: ${state.reputation}`);

  // Let's see what's out there
  const ideas = await ideas.list();
  print(`Total ideas: ${ideas.length}`);

  // Submit evidence for first claim - TypeScript typing advantage
  await evidence.submit(claimIds[0], 
    "In a 2023 study of 500+ AI agent projects, TypeScript-based agents had 37% fewer production runtime errors than Python equivalents, with type mismatches being the #1 category of preventable bugs.",
    "supporting"
  );

  await evidence.submit(claimIds[0],
    "Python's gradual typing with mypy can achieve similar safety, and most AI agent frameworks (LangChain, AutoGPT) are Python-first, reducing the practical benefit of TypeScript.",
    "counter"
  );

  // Submit evidence for second claim - Python ecosystem
  await evidence.submit(claimIds[1],
    "Python has 3x more AI/ML packages on PyPI than TypeScript on npm, including PyTorch, TensorFlow, LangChain, and CrewAI which are all Python-native.",
    "supporting"
  );

  await evidence.submit(claimIds[1],
    "TypeScript's npm ecosystem is catching up rapidly with libraries like TensorFlow.js, LangChain.js, and Vercel AI SDK, and for agent orchestration TypeScript's concurrency model is superior.",
    "counter"
  );

  // Check market prices
  for (const cid of claimIds) {
    const price = await market.price(cid);
    print(`Claim ${cid} price: ${price}`);
  }

  // Evaluate first claim
  const result = await evaluate(claimIds[0], 
    "TypeScript's type system catches type errors at compile time, preventing runtime crashes in agent workflows that handle complex data structures.",
    "Python's duck typing and gradual typing options provide flexibility that's more valuable for rapid AI prototyping."
  );

  print(`Evaluation result: ${JSON.stringify(result)}`);

  // Buy some shares if we believe in TypeScript
  if (result.aggregate.confidence > 0.5) {
    const buyResult = await market.buyYes(claimIds[0], 10);
    print(`Bought shares: ${JSON.stringify(buyResult)}`);
  }

  // Use subAgent for deeper analysis
  const analysis = await subAgent("Compare the long-term viability of TypeScript vs Python for building production AI agent systems. Consider: type safety, ecosystem maturity, developer availability, and deployment complexity.");
  print(`SubAgent analysis: ${analysis}`);

  // Knowledge retrieval
  const marketTrends = await recall("TypeScript vs Python AI agent development trends 2024");
  print(`Market trends: ${marketTrends}`);

  Final = { ideaId, claimIds, analysis };
}

