async function main() {
  // Examine current marketplace state
  const currentState = await state();
  print("Current state:", JSON.stringify(currentState, null, 2));

  // List existing ideas
  const existingIdeas = await ideas.list();
  print("Existing ideas:", JSON.stringify(existingIdeas, null, 2));

  // Check prices on existing claims
  for (const idea of existingIdeas) {
    for (const cid of idea.claimIds) {
      const price = await market.price(cid);
      print(`Claim ${cid}: price = ${price}`);
    }
  }

  // Propose a new idea with sharper claims
  const {ideaId, claimIds} = await ideas.propose({
    title: "TypeScript vs Python for AI Agent Development",
    summary: "Comparing static vs dynamic typing for building reliable AI agents",
    body: "TypeScript offers compile-time safety that catches type errors before runtime, reducing debugging time in complex agent workflows. Python's dynamic typing enables faster prototyping but leads to more runtime failures in production agent systems.",
    claims: [
      "TypeScript's static typing reduces runtime errors in AI agent workflows compared to Python's dynamic typing.",
      "Python's extensive AI/ML library ecosystem gives it a significant advantage for AI agent development over TypeScript."
    ]
  });

  print(`Proposed idea ${ideaId} with claims ${claimIds.join(", ")}`);

  // Submit evidence for claim 1 (TypeScript typing advantage)
  await evidence.submit(claimIds[0], 
    "TypeScript catches type mismatches at compile time, preventing entire classes of runtime errors that plague Python agent systems. For multi-agent coordination where message formats must be precise, TypeScript's type system acts as executable documentation.",
    "supporting");

  await evidence.submit(claimIds[0],
    "Python's dynamic typing allows rapid iteration and duck typing, which is valuable when agent interfaces evolve quickly during development. TypeScript's type annotations add boilerplate that slows down early prototyping.",
    "counter");

  // Submit evidence for claim 2 (Python library advantage)
  await evidence.submit(claimIds[1],
    "Python has mature libraries like LangChain, AutoGPT, CrewAI, and PyTorch that provide ready-made agent frameworks. TypeScript's agent ecosystem is newer and less comprehensive.",
    "supporting");

  await evidence.submit(claimIds[1],
    "TypeScript's npm ecosystem includes powerful tools like Zod for validation, LangChain.js, and Vercel AI SDK. For web-native agents, TypeScript integrates seamlessly with browser APIs and serverless runtimes.",
    "counter");

  // Evaluate both claims
  for (const cid of claimIds) {
    const ev = await evidence.list(cid);
    print(`Evidence for ${cid}:`, JSON.stringify(ev, null, 2));

    const result = await evaluate(cid, 
      ev.filter(e => e.stance === "supporting").map(e => e.excerpt),
      ev.filter(e => e.stance === "counter").map(e => e.excerpt)
    );
    print(`Evaluation for ${cid}:`, JSON.stringify(result, null, 2));
  }

  // Check updated prices
  for (const cid of claimIds) {
    const price = await market.price(cid);
    print(`Updated price for ${cid}: ${price}`);
  }

  // Buy shares on the most promising claim
  const claim1Price = await market.price(claimIds[0]);
  if (claim1Price < 0.6) {
    const buyResult = await market.buyYes(claimIds[0], 100);
    print("Bought 100 shares on claim 1:", JSON.stringify(buyResult));
  }

  Final = { ideaId, claimIds, status: "explored" };
}

