}

// Generate a branch at given position and angle
function createBranch(pos, angleY, angleX, length, radius) {
  const geo = new THREE.CylinderGeometry(radius * 0.5, radius, length, 6);
  const mesh = new THREE.Mesh(geo, branchMat);

  // Position at the branch point
  mesh.position.copy(pos);

  // Rotate: first around Y (horizontal direction), then around local X (upward angle)
  const quat = new THREE.Quaternion();
  const euler = new THREE.Euler(angleX, angleY, 0, 'YXZ');
  quat.setFromEuler(euler);
  mesh.quaternion.copy(quat);

  // Move the branch forward along its local axis so it extends from the trunk
  const forward = new THREE.Vector3(0, 1, 0);
  forward.applyQuaternion(quat);
  mesh.position.add(forward.multiplyScalar(length / 2));

  mesh.castShadow = true;
  mesh.receiveShadow = true;
  treeGroup.add(mesh);

