    const angleY = (i / numBranches) * Math.PI * 2 + Math.random() * 0.3;
    const angleX = Math.PI / 2 - (0.3 + Math.random() * 0.4); // upward angle
    const length = BRANCH_LENGTH_MIN + Math.random() * (BRANCH_LENGTH_MAX - BRANCH_LENGTH_MIN);
    const radius = BRANCH_RADIUS * (1 + Math.random() * 0.3);

    const pos = new THREE.Vector3(0, yPos, 0);
    const mesh = createBranch(pos, angleY, angleX, length, radius);
    branchMeshes.push(mesh);
  }
}

