      ).normalize();
      this.spawnBranch(branchPos, branchDir, trunkRadius * 0.6, 2 + Math.random() * 2);
    }
  }

  spawnBranch(startPos, parentDir, parentRadius, length) {
    const branchDir = parentDir.clone().add(
      new THREE.Vector3((Math.random() - 0.5) * 1.5, (Math.random() - 0.5) * 0.5, (Math.random() - 0.5) * 1.5)
    ).normalize();

    const branchRadius = parentRadius * (0.3 + Math.random() * 0.3);
    const segments = 3 + Math.floor(Math.random() * 3);
    const segLength = length / segments;

    let pos = startPos.clone();
    let dir = branchDir.clone();
    let rad = branchRadius;

    for (let i = 0; i < segments; i++) {
      const endPos = pos.clone().add(dir.clone().multiplyScalar(segLength));

      // Slight curve
      if (i > 0) {
        dir.x += (Math.random() - 0.5) * 0.2;
        dir.z += (Math.random() - 0.5) * 0.2;
        dir.normalize();
      }

      const cylinder = new THREE.Mesh(
        new THREE.CylinderGeometry(rad * 0.85, rad, segLength, 5),
        new THREE.MeshStandardMaterial({ color: 0x6b4423, roughness: 0.85 })
      );
      const midPoint = pos.clone().add(dir.clone().multiplyScalar(segLength / 2));
      cylinder.position.copy(midPoint);

      const up = new THREE.Vector3(0, 1, 0);
      const quat = new THREE.Quaternion().setFromUnitVectors(up, dir);
      cylinder.quaternion.copy(quat);

      cylinder.castShadow = true;
      cylinder.receiveShadow = true;
      this.group.add(cylinder);

      this.branches.push({
        mesh: cylinder,
        start: pos.clone(),
        end: endPos.clone(),
        radius: rad
      });

      pos = endPos;
      rad *= 0.8;

      // Sub-branches
      if (i >= 1 && Math.random() < 0.3) {
        const subDir = dir.clone().add(
          new THREE.Vector3((Math.random() - 0.5) * 1.2, (Math.random() - 0.5) * 0.3, (Math.random() - 0.5) * 1.2)
        ).normalize();
        this.spawnBranch(pos, subDir, rad, length * 0.5);
      }
    }

    // Leaves at end
    if (Math.random() < 0.7) {
      this.addLeafCluster(pos, 0.6 + Math.random() * 0.5);
    }
  }

  addLeafCluster(position, size) {
    const leafCount = 20 + Math.floor(Math.random() * 30);
    const leafMaterial = new THREE.MeshStandardMaterial({
      color: new THREE.Color().setHSL(0.25 + Math.random() * 0.1, 0.7, 0.4 + Math.random() * 0.3),
      roughness: 0.8
    });

    for (let i = 0; i < leafCount; i++) {
      const leaf = new THREE.Mesh(
        new THREE.SphereGeometry(size * (0.1 + Math.random() * 0.3), 3, 3),
        leafMaterial
      );
      leaf.position.set(
        position.x + (Math.random() - 0.5) * size * 2,
        position.y + (Math.random() - 0.5) * size * 1.5,
        position.z + (Math.random() - 0.5) * size * 2
      );
      leaf.castShadow = true;
      this.group.add(leaf);
      this.leaves.push(leaf);
    }
  }
}

