    function bounce() {
      if (!isRunning) return;

      x += dx;
      y += dy;

      // Bounce off walls
      if (x <= 0 || x + ballSize >= containerWidth) {
        dx = -dx;
        x = Math.max(0, Math.min(x, containerWidth - ballSize));
      }
      if (y <= 0 || y + ballSize >= containerHeight) {
        dy = -dy;
        y = Math.max(0, Math.min(y, containerHeight - ballSize));
      }

