      const speedFactor = parseInt(this.value);
      const currentSpeed = Math.sqrt(dx*dx + dy*dy);
      if (currentSpeed > 0) {
        const ratio = speedFactor / (currentSpeed || 1);
        dx *= ratio;
        dy *= ratio;
      } else {
        dx = speedFactor;
        dy = speedFactor * 0.75;
      }
    });

    // Start animation
    updateBallPosition();
    bounce();

    // Handle window resize - keep game container centered
    window.addEventListener('resize', function() {
      // Container size is fixed, just ensure it stays centered
    });

    // Cleanup on page unload
    window.addEventListener('beforeunload', function() {
      if (animationId) {
        cancelAnimationFrame(animationId);
      }
    });
