      // Speed up slightly with each click
      ball.dx *= 1.05;
      ball.dy *= 1.05;

      // Cap maximum speed
      const maxSpeed = 12;
      if (Math.abs(ball.dx) > maxSpeed) ball.dx = Math.sign(ball.dx) * maxSpeed;
      if (Math.abs(ball.dy) > maxSpeed) ball.dy = Math.sign(ball.dy) * maxSpeed;
    }
  });

  // Game loop
  function gameLoop() {
    if (!gameRunning) return;

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update and draw
    updateBall();
    drawBall();

    // Continue animation
    animationId = requestAnimationFrame(gameLoop);
  }

  // Reset game
  function resetGame() {
    score = 0;
    scoreElement.textContent = '0';
    ball.x = 300;
    ball.y = 200;
    ball.dx = 4;
    ball.dy = 3;
    ball.color = '#667eea';

    // Restart game loop if stopped
    if (!gameRunning) {
      gameRunning = true;
      gameLoop();
    }
  }

  // Start the game
  gameLoop();
</script>
</body>
