// --- Fractal Tree Builder ---
// Build branches that emerge FROM the trunk surface
function buildTree() {
  const treeGroup = new THREE.Group();

  // Trunk: a cylinder with branch attachment points on its surface
  const trunkHeight = 3.0;
  const trunkRadius = 0.4;
  const trunkGeo = new THREE.CylinderGeometry(trunkRadius * 0.7, trunkRadius, trunkHeight, 12);
  const trunkMat = new THREE.MeshLambertMaterial({ color: 0x8B5A2B });
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.y = trunkHeight / 2;
  trunk.castShadow = true;
  treeGroup.add(trunk);

  // Branch data: each branch starts from a point ON the trunk surface
  // angle around trunk, height offset, length, angle up, thickness
  const branches = [
    { angle: 0.2, height: 0.8, length: 1.2, upAngle: 0.5, thickness: 0.12 },
    { angle: 2.0, height: 1.0, length: 1.0, upAngle: 0.6, thickness: 0.10 },
    { angle: 3.8, height: 0.6, length: 1.4, upAngle: 0.4, thickness: 0.11 },
    { angle: 5.0, height: 1.4, length: 0.9, upAngle: 0.7, thickness: 0.09 },
    { angle: 1.5, height: 1.8, length: 1.1, upAngle: 0.5, thickness: 0.08 },
    { angle: 4.2, height: 2.0, length: 0.8, upAngle: 0.6, thickness: 0.07 },
    { angle: 2.8, height: 2.4, length: 0.7, upAngle: 0.5, thickness: 0.06 },
    { angle: 0.8, height: 2.6, length: 0.6, upAngle: 0.4, thickness: 0.05 },
  ];

  // Recursive branch builder
  function addBranch(parentPos, angle, heightOffset, length, upAngle, thickness, depth) {
    if (depth > 4) return;
    if (length < 0.2) return;

    // Start point: on trunk surface at given height
    const startX = parentPos.x + Math.cos(angle) * trunkRadius * 0.85;
    const startZ = parentPos.z + Math.sin(angle) * trunkRadius * 0.85;
    const startY = parentPos.y + heightOffset;

    // Direction: outward from trunk + upward
    const dirX = Math.cos(angle) * Math.cos(upAngle);
    const dirZ = Math.sin(angle) * Math.cos(upAngle);
    const dirY = Math.sin(upAngle);

    const endX = startX + dirX * length;
    const endZ = startZ + dirZ * length;
    const endY = startY + dirY * length;

    // Create branch cylinder
    const midX = (startX + endX) / 2;
    const midZ = (startZ + endZ) / 2;
    const midY = (startY + endY) / 2;
    const dx = endX - startX;
    const dz = endZ - startZ;
    const dy = endY - startY;
    const branchLen = Math.sqrt(dx*dx + dy*dy + dz*dz);

    if (branchLen < 0.05) return;

    const branchGeo = new THREE.CylinderGeometry(thickness * 0.5, thickness, branchLen, 6);
    const branchMat = new THREE.MeshLambertMaterial({ color: 0x7A4A1A });
    const branch = new THREE.Mesh(branchGeo, branchMat);
    branch.position.set(midX, midY, midZ);

    // Orient cylinder along direction
    const up = new THREE.Vector3(0, 1, 0);
    const dir = new THREE.Vector3(dx, dy, dz).normalize();
    const quat = new THREE.Quaternion().setFromUnitVectors(up, dir);
    branch.quaternion.copy(quat);
    branch.castShadow = true;
    treeGroup.add(branch);

    // Add leaf at tip if small enough
    if (length < 0.5 && depth >= 2) {
      const leafGeo = new THREE.SphereGeometry(0.15 + Math.random() * 0.1, 4);
      const leafMat = new THREE.MeshLambertMaterial({ color: new THREE.Color().setHSL(0.3 + Math.random() * 0.1, 0.8, 0.4) });
      const leaf = new THREE.Mesh(leafGeo, leafMat);
      leaf.position.set(endX, endY, endZ);
      treeGroup.add(leaf);
    }

    // Recursive sub-branches
    if (depth < 3) {
      const subCount = 2 + Math.floor(Math.random() * 2);
      for (let i = 0; i < subCount; i++) {
        const subAngle = angle + (i - subCount/2) * 0.8 + Math.random() * 0.3;
        const subUp = upAngle + 0.2 + Math.random() * 0.3;
        const subLen = length * (0.5 + Math.random() * 0.2);
        const subThick = thickness * 0.6;
        addBranch(
          new THREE.Vector3(endX, endY, endZ),
          subAngle, 0, subLen, subUp, subThick, depth + 1
        );
      }
    }
  }

  // Add branches from trunk surface
  for (const b of branches) {
    addBranch(
      new THREE.Vector3(0, 0, 0),
      b.angle, b.height, b.length, b.upAngle, b.thickness, 1
    );
  }

  // Add some random small branches near top
  for (let i = 0; i < 6; i++) {
    const ang = Math.random() * Math.PI * 2;
    const ht = 2.0 + Math.random() * 0.8;
    addBranch(
      new THREE.Vector3(0, 0, 0),
      ang, ht, 0.3 + Math.random() * 0.3, 0.3 + Math.random() * 0.4, 0.04, 2
    );
  }

  return treeGroup;
}

const tree = buildTree();
scene.add(tree);

// --- Player ---
