// Collision detection: check if player is inside tree branches
function checkCollision(pos) {
  // Simple: check distance from trunk center
  const trunkCenter = new THREE.Vector3(0, 0, 0);
  const toTrunk = new THREE.Vector3(pos.x, 0, pos.z);
  const distFromTrunk = toTrunk.length();
  if (distFromTrunk < 0.3 && pos.y > 0 && pos.y < 3.0) {
    return true; // inside trunk
  }
  return false;
}

// Find nearest branch surface for climbing
function findClosestBranch(pos) {
  // Simplified: check if near any branch by scanning tree children
  let closest = null;
  let minDist = 0.5;
  tree.children.forEach(child => {
    if (child.isMesh && child.geometry.type === 'CylinderGeometry') {
      const worldPos = new THREE.Vector3();
      child.getWorldPosition(worldPos);
      const dist = pos.distanceTo(worldPos);
      if (dist < minDist) {
        minDist = dist;
        closest = { pos: worldPos, obj: child };
      }
    }
  });
  return closest;
}

