  // End point of this branch
  const endPos = new THREE.Vector3().copy(startPos).addScaledVector(direction, length);

  // Add leaves at terminal branches
  if (depth >= 3 && depth <= maxDepth) {
    const leafCount = 3 + Math.floor(Math.random() * 3);
    for (let i = 0; i < leafCount; i++) {
      const leafGeo = new THREE.SphereGeometry(leafSize * (0.5 + Math.random() * 0.5), 4);
      const leafMat = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(0.25 + Math.random() * 0.1, 0.7, 0.4 + Math.random() * 0.3),
        roughness: 0.6
      });
      const leaf = new THREE.Mesh(leafGeo, leafMat);
      const offset = new THREE.Vector3(
        (Math.random() - 0.5) * 0.8,
        (Math.random() - 0.5) * 0.8,
        (Math.random() - 0.5) * 0.8
      );
      leaf.position.copy(endPos).add(offset);
      leaf.castShadow = true;
      treeGroup.add(leaf);
    }
  }

  // Recursively create child branches
  if (depth < maxDepth) {
    const numChildren = 2 + Math.floor(Math.random() * 2);
    for (let i = 0; i < numChildren; i++) {
      // Random direction within cone
      const angle = (i / numChildren) * Math.PI * 2 + Math.random() * 0.5;
      const spread = branchAngle * (0.6 + Math.random() * 0.4);

      // Create a random direction that deviates from parent direction
      const perp1 = new THREE.Vector3();
      const perp2 = new THREE.Vector3();
      if (Math.abs(direction.y) < 0.9) {
        perp1.crossVectors(direction, new THREE.Vector3(0, 1, 0)).normalize();
      } else {
        perp1.crossVectors(direction, new THREE.Vector3(1, 0, 0)).normalize();
      }
      perp2.crossVectors(direction, perp1).normalize();

      const childDir = new THREE.Vector3()
        .copy(direction)
        .multiplyScalar(Math.cos(spread))
        .add(perp1.multiplyScalar(Math.sin(spread) * Math.cos(angle)))
        .add(perp2.multiplyScalar(Math.sin(spread) * Math.sin(angle)))
        .normalize();

      const childLength = length * branchShrink * (0.8 + Math.random() * 0.4);
      const childRadius = radius * branchShrink * (0.7 + Math.random() * 0.3);

      createBranch(endPos, childDir, childLength, childRadius, depth + 1);
    }
  }
}

