// --- Collision Detection ---
function getClosestBranchPoint(pos) {
  let closestDist = Infinity;
  let closestNormal = new THREE.Vector3(0, 1, 0);
  let closestPoint = null;

  for (const mesh of branchMeshes) {
    // Simple sphere-based collision using mesh position and bounding sphere
    const meshPos = mesh.position;
    const radius = mesh.geometry.parameters.radiusTop || 0.3;
    const height = mesh.geometry.parameters.height || 1;

    // Project player onto cylinder axis
    const dir = new THREE.Vector3(0, 1, 0).applyQuaternion(mesh.quaternion);
    const toPlayer = new THREE.Vector3().copy(pos).sub(meshPos);
    const t = toPlayer.dot(dir);
    const clampedT = Math.max(-height/2, Math.min(height/2, t));
    const closestOnAxis = new THREE.Vector3().copy(meshPos).addScaledVector(dir, clampedT);
    const diff = new THREE.Vector3().copy(pos).sub(closestOnAxis);
    const dist = diff.length();

    if (dist < closestDist && dist < radius + 0.5) {
      closestDist = dist;
      closestNormal.copy(diff).normalize();
      closestPoint = closestOnAxis;
    }
  }

  return { point: closestPoint, normal: closestNormal, dist: closestDist };
}

